// Anillos comprimidos: deltas en centesimas de grado, base36. Se expanden una
// sola vez al arrancar y los periodos que comparten silueta comparten tambien
// el mismo array en memoria, asi que esto ahorra archivo y RAM a la vez.
function __decRing(s){var out=[],px=0,py=0,parts=s.split(';');
  for(var i=0;i<parts.length;i++){var t=parts[i];if(!t)continue;var c=t.indexOf(',');
    px+=parseInt(t.slice(0,c),36);py+=parseInt(t.slice(c+1),36);out.push([px/100,py/100]);}
  return out;}
(function(){
  var D=new Array(__RG.length);
  for(var k=0;k<__RG.length;k++)D[k]=__decRing(__RG[k]);
  for(var i=0;i<CIVILIZATIONS.length;i++){var cv=CIVILIZATIONS[i];
    for(var j=0;j<cv.periods.length;j++){var p=cv.periods[j];
      if(typeof p.rings!=='string')continue;
      if(!p.rings.length){p.rings=[];continue;}
      var ids=p.rings.split(','),rs=new Array(ids.length);
      for(var m=0;m<ids.length;m++)rs[m]=D[parseInt(ids[m],36)];
      p.rings=rs;}}
})();
