// ── Layer altitude scheme ───────────────────────────────────────────────────
// Each process layer renders its area/path at its OWN radius above the globe
// surface (1.0), spaced 0.004 apart, so two layers active at once never sit
// on the exact same shell -- previously civilizations and languages were
// BOTH at 1.016 (literally identical) and religion at 1.017 (0.001 away),
// which caused z-fighting/flicker and made it impossible to tell which
// translucent blob belonged to which layer when several were toggled on
// together. Order (innermost -> outermost) follows "static territory" to
// "dynamic overlay": civilizations 1.014, religion 1.018, languages 1.022,
// wars 1.026, routes 1.030, migration 1.034.
// ── Capa de territorios fusionada ───────────────────────────────────────────
// Cada territorio (civilizacion + periodo, la clave 'k') se triangula UNA vez
// y se guarda como buffers sueltos. Al pintar, los buffers de los territorios
// activos se concatenan en una sola malla de relleno y una sola geometria de
// perimetro: cuatro llamadas de dibujo en total en vez de miles.
var civCache=Object.create(null);       // clave -> {fp,fc,lp,lc,etiqueta,civId,uso}
var civModo='';                         // firma del modo de dibujo: 2D/3D + nombres
var civUso=0;
var CIV_CACHE_MAX=700;
var civFillMesh=null,civLineas=[],civTriIds=[],civPuntos=null;
var civEtiquetas=Object.create(null);   // clave -> sprite en escena

function avisarRN(m){
  if(window.ReactNativeWebView)window.ReactNativeWebView.postMessage(JSON.stringify(m));
}
function ponerAtributo(geo,nombre,arr,tam){
  var at=geo.getAttribute(nombre);
  if(at&&at.array.length===arr.length){at.copyArray(arr);at.needsUpdate=true;}
  else geo.setAttribute(nombre,new THREE.BufferAttribute(arr,tam));
  geo.setDrawRange(0,arr.length/tam);
  if(nombre==='position')geo.computeBoundingSphere();
}
// ── El velo de la tierra sin entidad ──────────────────────────────────────
// Anillos de base_tierra.js (tierra firme menos vacios permanentes), pintados
// una vez por proyeccion a un radio por debajo de las civilizaciones. Normal
// blending y poca opacidad: un velo, no una capa.
var baseTierraRings=[],baseTierraMesh=null;
function construirBaseTierra(){
  if(baseTierraMesh){procesGroup.remove(baseTierraMesh);baseTierraMesh.geometry.dispose();baseTierraMesh.material.dispose();baseTierraMesh=null;}
  if(!baseTierraRings.length)return;
  var verts=[];
  for(var i=0;i<baseTierraRings.length;i++){
    var fv=fillVertsFromRing(densifyRing(baseTierraRings[i],4),1.011);
    for(var a=0;a<fv.length;a++)verts.push(fv[a]);
  }
  var geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.BufferAttribute(new Float32Array(verts),3));
  geo.computeBoundingSphere();
  baseTierraMesh=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color:0xcbbd9e,transparent:true,opacity:0.20,side:THREE.DoubleSide,depthWrite:false}));
  baseTierraMesh.renderOrder=1;
  baseTierraMesh.visible=!!state.civilizations&&state.baseOn!==false;
  procesGroup.add(baseTierraMesh);
}
// Las aristas de las areas culturales van en su propia geometria, con un solo
