  suggestionsRow:   { flexDirection:'row', flexWrap:'wrap', gap:8, paddingTop:2, paddingBottom:8 },
  suggestionChip:   { maxWidth:'100%', paddingVertical:9, paddingHorizontal:13, borderRadius:14, backgroundColor:'rgba(55,138,221,0.10)', borderWidth:0.5, borderColor:'rgba(55,138,221,0.35)' },
  suggestionChipTxt:{ color:'#7EB6EE', fontSize:12.5, fontWeight:'600', lineHeight:17 },
  inputRow:    { flexDirection:'row', alignItems:'flex-end', gap:10, paddingHorizontal:16, paddingTop:10, paddingBottom:Platform.OS === 'ios' ? 30 : 16, borderTopWidth:0.5, borderColor:'rgba(255,255,255,0.08)' },
  input:       { flex:1, maxHeight:100, color:'#fff', fontSize:14, backgroundColor:'rgba(255,255,255,0.06)', borderRadius:16, borderWidth:0.5, borderColor:'rgba(255,255,255,0.14)', paddingHorizontal:14, paddingVertical:10 },
  sendBtn:     { width:38, height:38, borderRadius:19, backgroundColor:'#378ADD', alignItems:'center', justifyContent:'center' },
